143	loop_default_sleep :: proc(ms: int) {
144		time.sleep(time.Duration(ms) * time.Millisecond)
145	}
146	
147	// 分片睡眠，返回 false 表示中途被取消。sleep_fn 只是测试注入点，切片逻辑
148	// 仍在引擎里，保证默认实现和测试替身都尊重取消。
149	loop_sleep_cancellable :: proc(l: ^Loop, ms: int) -> bool {
150		remaining := ms
151		for remaining > 0 {
152			if platform.cancel_token_cancelled(l.cancel) {
153				return false
154			}
155			slice := min(remaining, RETRY_SLEEP_SLICE_MS)
156			l.sleep_fn(slice)
157			remaining -= slice
158		}
159		return !platform.cancel_token_cancelled(l.cancel)
160	}
