162	// turn_end 覆盖一轮的量；handoff 与 session_title 是独立的一次模型调用
163	// （manual handoff 没有 turn），都要累加，否则 session_end.usage 会漏掉它们。
164	historical_usage_from_events :: proc(events: []Event) -> Usage {
165		total := Usage{}
166		for ev in events {
167			switch ev.type {
168			case EVENT_TURN_END:
169				end: Turn_End_Event
170				if json.unmarshal_string(ev.line, &end) == nil {
171					total = usage_add(total, end.usage)
172				}
173			case EVENT_HANDOFF:
174				handoff: Handoff_Event
175				if json.unmarshal_string(ev.line, &handoff) == nil {
176					if usage, has_usage := handoff.usage.?; has_usage {
177						total = usage_add(total, usage)
178					}
179				}
180			case EVENT_SESSION_TITLE:
181				title: Session_Title_Event
182				if json.unmarshal_string(ev.line, &title) == nil {
183					if usage, has_usage := title.usage.?; has_usage {
184						total = usage_add(total, usage)
185					}
186				}
187			}
188		}
189		return total
190	}
