192	next_turn_from_events :: proc(events: []Event) -> int {
193		max_turn := 0
194		for ev in events {
195			if ev.type != EVENT_TURN_START {
196				continue
197			}
198			start: Turn_Start_Event
199			if json.unmarshal_string(ev.line, &start) == nil && start.turn > max_turn {
200				max_turn = start.turn
201			}
202		}
203		return max_turn + 1
204	}
