206	loop_init :: proc(
207		project: Project,
208		settings: ^Settings,
209		store: ^Transcript_Store,
210		registry: tool.Registry,
211		active_tools: []string,
212		model, agent_name, session_id: string,
213		agent_depth, max_steps, max_tokens: int,
214		cancel: ^platform.Cancel_Token,
215		events: []Event,
216		emitter: Emitter,
217	) -> Loop {
218		// 父 session 是冻结在 session_start 里的信息，loop 直接从事件恢复，
219		// 避免把已经在 transcript 中的字段再从 Session 传一遍。
220		parent_session_id: Maybe(string)
221		if start, found := last_session_start(events); found {
222			parent_session_id = start.parent_session_id
223		}
224		loop := Loop {
225			project = project,
226			settings = settings,
227			store = store,
228			provider = provider_init(settings),
229			provider_call = provider_stream,
230			sleep_fn = loop_default_sleep,
231			registry = registry,
232			active_tools = active_tools,
233			model = model,
234			agent_name = agent_name,
235			session_id = session_id,
236			parent_session_id = parent_session_id,
237			agent_depth = agent_depth,
238			max_steps = max_steps,
239			max_tokens = max_tokens,
240			cancel = cancel,
241			emitter = emitter,
242			historical_usage = historical_usage_from_events(events),
243			turn = next_turn_from_events(events),
244			calibration_percent = 100,
245			// 子代理的职责是回一个结论，不是开新 session。
246			handoff_enabled = agent_depth == 0,
247		}
248		loop.events = make([dynamic]Event, len(events), len(events) + 16)
249		copy(loop.events[:], events)
250		loop.initial_event_count = len(events)
251		loop.attempt_text = make([dynamic]byte, 0, 256)
252		return loop
253	}
