255	loop_destroy :: proc(l: ^Loop) {
256		// l.events 的前 len(initial_events) 项由调用方（session.events）持有，
257		// 只释放本 loop 追加的那部分行。type 永远是静态字面量，不释放。
258		for i in l.initial_event_count ..< len(l.events) {
259			delete(l.events[i].line)
260		}
261		delete(l.events)
262		delete(l.attempt_text)
263		delete(l.last_text)
264		loop_release_owned(l)
