281	loop_append :: proc(l: ^Loop, event: any, header: Event_Header) -> Error {
282		line, werr := transcript_append_line(l.store, event)
283		if !is_ok(werr) {
284			return werr
285		}
286		ev := Event {
287			v = header.v,
288			seq = header.seq,
289			ts = header.ts,
290			type = header.type,
291			line = line,
292		}
293		append(&l.events, ev)
294		if l.emitter.on_transcript != nil {
295			l.emitter.on_transcript(l.emitter.user, ev)
