306	loop_start_message :: proc(l: ^Loop, model: string) -> Error {
307		if l.message_started {
308			return ok_error()
309		}
310		id := l.current_message_id
311		if len(id) == 0 {
312			generated := uuid.generate_v4()
313			id = uuid.to_string(generated, context.allocator)
314			l.current_message_id = id
315		}
316		message_model := model
317		if len(message_model) == 0 {
318			message_model = l.model
319		}
320		h := make_header(l.store, EVENT_MESSAGE_START)
321		ev := Message_Start_Event {
322			header = h,
323			message_id = id,
324			role = ROLE_ASSISTANT,
325			model = message_model,
326		}
327		if err := loop_append(l, ev, h); !is_ok(err) {
328			return err
329		}
330		l.message_started = true
331		return ok_error()
332	}
