334	// 大于阈值的内容写入 blob，失败时调用方决定是保留原文还是报错。
335	make_text_block :: proc(l: ^Loop, text: string) -> (Content_Block, Error) {
336		block := Content_Block{type = BLOCK_TEXT, text = text}
337		stored, berr := content_or_blob(l.store, transmute([]byte)text)
338		if !is_ok(berr) {
339			return block, berr
340		}
341		if stored.has_blob {
342			block.text = nil
343			block.text_ref = stored.ref
344			block.text_bytes = stored.bytes
345			block.text_preview = stored.preview
346		}
347		return block, ok_error()
348	}
