350	loop_write_message_end :: proc(l: ^Loop, end: Provider_Message_End) -> Error {
351		if err := loop_start_message(l, ""); !is_ok(err) {
352			return err
353		}
354		blocks := make([dynamic]Content_Block, 0, 2)
355		defer delete(blocks)
356		if len(end.text) > 0 {
357			block, berr := make_text_block(l, end.text)
358			if !is_ok(berr) {
359				return berr
360			}
361			append(&blocks, block)
362		}
363		for call in end.tool_calls {
364			block := Content_Block{type = BLOCK_TOOL_USE, id = call.id, name = call.name}
365			args_text := platform.json_arguments_string(call.input)
366			defer delete(args_text)
367			stored, berr := content_or_blob(l.store, transmute([]byte)args_text)
368			if !is_ok(berr) {
369				return berr
370			}
371			if stored.has_blob {
372				block.input = nil
373				block.input_ref = stored.ref
374				block.input_bytes = stored.bytes
375				block.input_preview = stored.preview
376			} else {
377				block.input = call.input
378			}
379			append(&blocks, block)
380		}
381	
382		var_usage: Maybe(Usage)
383		if usage_has_any(end.usage) {
384			var_usage = end.usage
385			l.turn_usage = usage_add(l.turn_usage, end.usage)
386			// 这一次请求的真实输入长度。transcript 只追加，所以它就是下一步
387			// messages 的前缀长度，可以直接拿来校准下一次估算。
388			if observed, has_observed := end.usage.input_tokens.?; has_observed {
389				l.last_observed_input = observed
390			}
391		}
392		var_reasoning: Maybe(string)
393		if len(end.reasoning) > 0 {
394			var_reasoning = end.reasoning
395		}
396		h := make_header(l.store, EVENT_MESSAGE_END)
397		ev := Message_End_Event {
398			header = h,
399			message_id = l.current_message_id,
400			role = ROLE_ASSISTANT,
401			content = blocks[:],
402			stop_reason = stop_reason_string(end.stop_reason),
403			usage = var_usage,
404			reasoning = var_reasoning,
405		}
406		if err := loop_append(l, ev, h); !is_ok(err) {
407			return err
408		}
409		if len(end.text) > 0 {
410			// 每步都会走到这里；先释放上一步的副本，否则一个 turn 里每次覆盖都漏一份。
411			delete(l.last_text)
412			l.last_text = strings.clone(end.text)
413		}
414		l.message_started = false
415		l.current_message_id = ""
416		return ok_error()
417	}
