541	// 所有退出点都要填 usage 与 session_usage。stream-json 的 turn_end 用量来自
542	// 这里；取消路径漏填会让调用方看到 0 用量，与 transcript 不一致。
543	loop_fill_usage :: proc(l: ^Loop, result: ^Loop_Result, num_steps: int) {
544		result.num_steps = num_steps
545		result.usage = l.turn_usage
546		result.session_usage = usage_add(l.historical_usage, l.turn_usage)
547	}
