549	// 可报告的终止路径：turn_end 写不进去就是致命错误，不能当成功返回。
550	// transcript 是唯一事实来源，缺尾行意味着 usage 与上下文快照丢失。
551	loop_finish_turn :: proc(l: ^Loop, result: ^Loop_Result, stop_reason: string, num_steps: int) -> bool {
552		result.stop_reason = stop_reason
553		loop_fill_usage(l, result, num_steps)
554		if err := loop_write_turn_end(l, stop_reason); !is_ok(err) {
555			result.error_kind = .Internal
556			result.fatal_error = err.message
557			return false
558		}
