577	// 把工具返回的图片写成 blob，返回事件引用。无论成败都在这里释放图片
578	// 原始字节：transcript 与后续投影只依赖 blob 引用。
579	persist_tool_images :: proc(
580		project: Project,
581		images: []tool.Tool_Image,
582	) -> ([]Tool_Image_Ref, string) {
583		refs := make([dynamic]Tool_Image_Ref, 0, len(images))
584		for image in images {
585			image_bytes := len(image.data)
586			sha, berr := blob_write(project, image.data)
587			delete(image.data)
588			if !is_ok(berr) {
589				delete(refs)
590				return nil, "failed to persist image blob"
591			}
592			append(
593				&refs,
594				Tool_Image_Ref {
595					name = image.name,
596					mime_type = image.mime_type,
597					ref = sha,
598					bytes = image_bytes,
599				},
600			)
601		}
602		return refs[:], ""
603	}
