605	loop_execute_tools :: proc(l: ^Loop) -> (cancelled: bool, err: Error, error_kind: Error_Kind) {
606		for call in l.pending_calls {
607			if platform.cancel_token_cancelled(l.cancel) {
608				_ = loop_write_cancel(l, SCOPE_STEP, l.current_tool_call_id)
609				loop_try_write_turn_end(l, STOP_REASON_CANCELLED)
610				return true, ok_error(), .None
611			}
612	
613			l.current_tool_call_id = call.id
614			args_text := platform.json_arguments_string(call.input)
615			defer delete(args_text)
616			start_ev := Tool_Execution_Start_Event {
617				tool_call_id = call.id,
618				name = call.name,
619			}
620			stored, berr := content_or_blob(l.store, transmute([]byte)args_text)
621			if !is_ok(berr) {
622				_ = loop_write_error(l, SCOPE_SESSION, .None, berr.message, false, 1)
623				return false, berr, .Tool
624			}
625			if stored.has_blob {
626				start_ev.args = nil
627				start_ev.args_ref = stored.ref
628				start_ev.args_bytes = stored.bytes
629				start_ev.args_preview = stored.preview
630			} else {
631				start_ev.args = call.input
632			}
633			h := make_header(l.store, EVENT_TOOL_EXECUTION_START)
634			start_ev.header = h
635			if aerr := loop_append(l, start_ev, h); !is_ok(aerr) {
636				return false, aerr, .Internal
637			}
638			progress(l, .Block, "### %s", call.name)
639	
640			tool_ctx := tool.Tool_Context {
641				cwd = l.project.root,
642				project = l.project,
643				cancel = l.cancel,
644				session_id = l.session_id,
645				parent_session_id = l.parent_session_id,
646				tool_call_id = call.id,
647				agent_name = l.agent_name,
648				agent_depth = l.agent_depth,
649				transcript_path = l.store.path,
650				on_update = loop_tool_update,
651				update_user = l,
652				on_progress = l.emitter.on_progress,
653				progress_user = l.emitter.user,
654			}
