loop_release_owned :: proc(l: ^Loop) {
	loop_release_message_id(l)
	loop_release_calls(l)
}

loop_release_message_id :: proc(l: ^Loop) {
	delete(l.owned_message_id)
	l.owned_message_id = ""
	l.current_message_id = ""
}

// 消息 id 的一切写入都走这里：释放点唯一，current_message_id 永远指向
// owned_message_id，不会出现「别名还活着但内容已释放」的状态。
loop_set_message_id :: proc(l: ^Loop, id: string) {
	loop_release_message_id(l)
	l.owned_message_id = strings.clone(id)
	l.current_message_id = l.owned_message_id
}

// message_end 里 loop 只接管 tool call 的 id/name/input：此时 message_id 还要
// 写进 message_end 事件，不能跟着一起释放。
loop_release_calls :: proc(l: ^Loop) {
	for call in l.owned_calls {
		delete(call.id)
		delete(call.name)
		// input 树由 provider 的 json.parse_string 用 context.allocator 建出来，
		// 全仓只有这里负责回收。
		json.destroy_value(call.input)
	}
	delete(l.owned_calls)
	l.owned_calls = nil
}

