loop_test_poison_backing2: runtime.Allocator

poison2 :: proc(
	allocator_data: rawptr,
	mode: runtime.Allocator_Mode,
	size, alignment: int,
	old_memory: rawptr,
	old_size: int,
	location := #caller_location,
) -> ([]byte, runtime.Allocator_Error) {
	if mode == .Free && old_memory != nil && old_size > 0 {
		freed := transmute([]byte)runtime.Raw_Slice{data = old_memory, len = old_size}
		for i in 0 ..< len(freed) {
			freed[i] = 0xAB
		}
	}
	return loop_test_poison_backing2.procedure(
		loop_test_poison_backing2.data,
		mode,
		size,
		alignment,
		old_memory,
		old_size,
		location,
	)
}

